	public void SetCategory(int category)
	{
		this.category = category;
		switch (category)
		{
		case 0:
			values = new float[25];
			upgradePath = new UpgradePath[2];
			break;
		case 1:
			values = new float[13];
			upgradePath = new UpgradePath[2];
			break;
