			upgradePath = new UpgradePath[2];
			break;
		case 4:
			values = new float[1];
			upgradePath = new UpgradePath[1];
			break;
		case 6:
			values = new float[1];
			upgradePath = new UpgradePath[1];
			break;
		case 5:
			values = new float[3];
			upgradePath = new UpgradePath[1];
			break;
		case 7:
			values = new float[1];
			upgradePath = new UpgradePath[1];
			break;
		}
	}

